insert into question_bank (curriculum_id, day_num, difficulty, question, type, options, answer, explanation) values
  ('english_grammar', 16, 'beginner', '"Walking home, I met her." 이 분사구문이 나타내는 의미는?', 'multiple_choice', '["시간(~하다가)","이유","조건","양보"]'::jsonb, '시간(~하다가)', '집에 걸어가는 도중이라는 시간을 나타내는 분사구문입니다.'),
  ('english_grammar', 16, 'beginner', '"Being tired, he went to bed." 이 분사구문이 나타내는 의미는?', 'multiple_choice', '["이유(~해서)","시간","조건","양보"]'::jsonb, '이유(~해서)', '피곤해서라는 이유를 나타내는 분사구문입니다.'),
  ('english_grammar', 16, 'beginner', '"Turning left, you''ll find the bank." 이 분사구문이 나타내는 의미는?', 'multiple_choice', '["조건(~하면)","시간","이유","양보"]'::jsonb, '조건(~하면)', '왼쪽으로 돌면이라는 조건을 나타내는 분사구문입니다.'),
  ('english_grammar', 16, 'beginner', '분사구문을 만들 때 접속사 다음 첫 번째로 하는 일은?', 'multiple_choice', '["접속사를 삭제한다","동사를 V-ing로 바꾼다","주어를 삭제한다","부정어를 추가한다"]'::jsonb, '접속사를 삭제한다', '분사구문은 접속사를 삭제하는 것으로 시작합니다.'),
  ('english_grammar', 16, 'beginner', '주절과 주어가 같을 때 분사구문에서 어떻게 하는가?', 'multiple_choice', '["주어를 삭제한다","주어를 그대로 둔다","주어를 목적격으로 바꾼다","주어를 소유격으로 바꾼다"]'::jsonb, '주어를 삭제한다', '주어가 같으면 분사구문에서 주어를 삭제합니다.'),
  ('english_grammar', 16, 'beginner', '분사구문에서 동사는 어떤 형태로 바뀌는가?', 'multiple_choice', '["V-ing","p.p.","동사원형","to부정사"]'::jsonb, 'V-ing', '분사구문의 동사는 V-ing 형태로 바뀝니다.'),
  ('english_grammar', 16, 'beginner', '부정 분사구문을 만들 때 V-ing 앞에 붙이는 것을 쓰시오.', 'short_answer', null, 'not', '부정 분사구문은 not + V-ing 형태입니다.'),
  ('english_grammar', 16, 'beginner', '주절보다 앞선 시제를 나타내는 분사구문의 형태를 쓰시오 (___ + p.p.).', 'short_answer', null, 'having', '완료 분사구문은 having + p.p. 형태로 주절보다 앞선 시제를 나타냅니다.'),
  ('english_grammar', 16, 'intermediate', '"Not knowing the answer, he was silent." 이 문장을 접속사를 살려 다시 쓴 것으로 옳은 것은?', 'multiple_choice', '["Because he didn''t know the answer, he was silent.","Because he knew the answer, he was silent.","If he didn''t know the answer, he was silent.","Although he didn''t know the answer, he was silent."]'::jsonb, 'Because he didn''t know the answer, he was silent.', 'not knowing은 이유를 나타내는 부정 분사구문이므로 because절로 풀 수 있습니다.'),
  ('english_grammar', 16, 'intermediate', '"Having finished the work, she went home." 이 문장에서 알 수 있는 사실은?', 'multiple_choice', '["일을 끝낸 것이 집에 간 것보다 먼저 일어났다","일을 끝낸 것과 집에 간 것이 동시에 일어났다","그녀는 일을 끝내지 못했다","그녀는 집에 가지 않았다"]'::jsonb, '일을 끝낸 것이 집에 간 것보다 먼저 일어났다', '완료 분사구문 Having finished는 주절보다 먼저 일어난 일을 나타냅니다.'),
  ('english_grammar', 16, 'intermediate', '"(Being) Written in English, the book is hard to read."에서 Being을 생략할 수 있는 이유는?', 'multiple_choice', '["수동 분사구문에서 Being은 생략 가능하기 때문","능동 분사구문이기 때문","완료 분사구문이기 때문","부정 분사구문이기 때문"]'::jsonb, '수동 분사구문에서 Being은 생략 가능하기 때문', '수동 분사구문 Being + p.p.에서 Being은 흔히 생략됩니다.'),
  ('english_grammar', 16, 'intermediate', '"She sat reading a book."에서 reading이 나타내는 의미는?', 'multiple_choice', '["동시동작(~하면서)","시간","이유","조건"]'::jsonb, '동시동작(~하면서)', '앉아서 책을 읽는 동시동작을 나타내는 분사구문입니다.'),
  ('english_grammar', 16, 'intermediate', '"Admitting he''s wrong, I still like him."이 나타내는 의미는?', 'multiple_choice', '["양보(비록 ~이지만)","시간","이유","조건"]'::jsonb, '양보(비록 ~이지만)', '그가 틀렸다는 것을 인정하지만이라는 양보의 의미입니다.'),
  ('english_grammar', 16, 'intermediate', '다음 중 분사구문으로 옳게 바꾼 것은? "Because it was raining, we stayed home."', 'multiple_choice', '["It raining, we stayed home.","Raining, we stayed home.","It rained, we stayed home.","To rain, we stayed home."]'::jsonb, 'It raining, we stayed home.', '종속절의 주어(it)가 주절의 주어와 다르므로 주어를 남긴 독립분사구문이 됩니다.'),
  ('english_grammar', 16, 'intermediate', '"Being written in English, the book is hard to read."에서 생략 가능한 단어를 쓰시오.', 'short_answer', null, 'Being', '수동 분사구문의 Being은 생략할 수 있습니다.'),
  ('english_grammar', 16, 'intermediate', '분사구문의 의미상 주어가 주절의 주어와 다를 때 분사 앞에 주어를 남겨두는 구문을 무엇이라 하는가?', 'short_answer', null, '독립분사구문', '주어가 다를 때는 분사 앞에 주어를 남긴 독립분사구문을 씁니다.'),
  ('english_grammar', 16, 'advanced', '"Having been invited, she attended the party."의 시제 구조는?', 'multiple_choice', '["완료 수동 분사구문","단순 수동 분사구문","완료 능동 분사구문","단순 능동 분사구문"]'::jsonb, '완료 수동 분사구문', 'Having been + p.p.는 완료와 수동이 결합된 분사구문입니다.'),
  ('english_grammar', 16, 'advanced', '다음 중 어법상 옳은 것은?', 'multiple_choice', '["Generally speaking, exercise is good for health.","Generally spoken, exercise is good for health.","Generally to speak, exercise is good for health.","Generally spoke, exercise is good for health."]'::jsonb, 'Generally speaking, exercise is good for health.', 'Generally speaking은 ''일반적으로 말하면''이라는 관용적 분사구문입니다.'),
  ('english_grammar', 16, 'advanced', '"Weather permitting, we will go on the picnic."에서 Weather의 역할은?', 'multiple_choice', '["분사구문의 독립적인 의미상 주어","주절의 주어","목적어","보어"]'::jsonb, '분사구문의 독립적인 의미상 주어', '주절의 주어(we)와 다른 독립적인 의미상 주어입니다.'),
  ('english_grammar', 16, 'advanced', '다음 중 완료 분사구문으로 옳은 것은?', 'multiple_choice', '["Having lost his keys, he couldn''t enter the house.","Losing his keys, he couldn''t enter the house.","Lost his keys, he couldn''t enter the house.","Having losing his keys, he couldn''t enter the house."]'::jsonb, 'Having lost his keys, he couldn''t enter the house.', '완료 분사구문은 Having + p.p. 형태입니다.'),
  ('english_grammar', 16, 'advanced', '"Judging from his accent, he must be from the South."에서 Judging from은 어떤 표현인가?', 'multiple_choice', '["관용적 분사구문(~로 판단하건대)","완료 분사구문","수동 분사구문","부정 분사구문"]'::jsonb, '관용적 분사구문(~로 판단하건대)', 'Judging from은 ''~로 판단하건대''라는 뜻의 관용적 분사구문입니다.'),
  ('english_grammar', 16, 'advanced', '다음 중 어법상 틀린 것은?', 'multiple_choice', '["Having finish his homework, he went out.","Having finished his homework, he went out.","Not having finished his homework, he stayed in.","Having been finished, the homework was submitted."]'::jsonb, 'Having finish his homework, he went out.', 'having 뒤에는 과거분사(finished)가 와야 하는데 finish(동사원형)가 왔으므로 틀렸습니다.'),
  ('english_grammar', 16, 'advanced', '''일반적으로 말하면''이라는 뜻의 관용적 분사구문을 쓰시오.', 'short_answer', null, 'Generally speaking', 'Generally speaking은 ''일반적으로 말하면''이라는 관용 표현입니다.'),
  ('english_grammar', 16, 'advanced', '''~로 판단하건대''라는 뜻의 관용적 분사구문을 쓰시오.', 'short_answer', null, 'Judging from', 'Judging from은 ''~로 판단하건대''라는 관용 표현입니다.'),
  ('english_grammar', 17, 'beginner', '"She is as tall as her brother."는 어떤 비교 표현인가?', 'multiple_choice', '["원급 비교","비교급","최상급","비교급 강조"]'::jsonb, '원급 비교', 'as + 형용사 + as는 원급 비교입니다.'),
  ('english_grammar', 17, 'beginner', '"She is taller than her sister."는 어떤 비교 표현인가?', 'multiple_choice', '["비교급","원급 비교","최상급","동등 비교"]'::jsonb, '비교급', '형용사 + -er + than은 비교급입니다.'),
  ('english_grammar', 17, 'beginner', '"He is the tallest in the class."는 어떤 비교 표현인가?', 'multiple_choice', '["최상급","비교급","원급 비교","동등 비교"]'::jsonb, '최상급', 'the + 형용사 + -est는 최상급입니다.'),
  ('english_grammar', 17, 'beginner', 'good의 비교급으로 옳은 것은?', 'multiple_choice', '["better","gooder","more good","goodest"]'::jsonb, 'better', 'good은 불규칙 변화로 better가 비교급입니다.'),
  ('english_grammar', 17, 'beginner', 'beautiful의 비교급으로 옳은 것은?', 'multiple_choice', '["more beautiful","beautifuler","beautifulest","most beautiful"]'::jsonb, 'more beautiful', '장음절 형용사는 more + 형용사로 비교급을 만듭니다.'),
  ('english_grammar', 17, 'beginner', 'bad의 최상급으로 옳은 것은?', 'multiple_choice', '["the worst","the baddest","the more bad","the most bad"]'::jsonb, 'the worst', 'bad는 불규칙 변화로 the worst가 최상급입니다.'),
  ('english_grammar', 17, 'beginner', '원급 비교의 부정형을 쓰시오 (not ___ ~ as).', 'short_answer', null, 'as', '원급 비교의 부정은 not as ~ as입니다.'),
  ('english_grammar', 17, 'beginner', '많음을 나타내는 many/much의 비교급을 쓰시오.', 'short_answer', null, 'more', 'many/much의 비교급은 more입니다.'),
  ('english_grammar', 17, 'intermediate', '"He is not as fast as her."의 의미로 옳은 것은?', 'multiple_choice', '["그는 그녀보다 빠르지 않다","그는 그녀보다 빠르다","그는 그녀만큼 빠르다","그는 매우 빠르다"]'::jsonb, '그는 그녀보다 빠르지 않다', 'not as ~ as는 ''~만큼 ~하지 않다''는 뜻입니다.'),
  ('english_grammar', 17, 'intermediate', '"She is much taller than him."에서 much의 역할은?', 'multiple_choice', '["비교급 강조","최상급 강조","동등 비교","부정"]'::jsonb, '비교급 강조', 'much는 비교급 taller를 강조합니다.'),
  ('english_grammar', 17, 'intermediate', '"The more you study, the smarter you get."과 같은 구조로 옳은 것은?', 'multiple_choice', '["The harder you work, the more you earn.","The hard you work, the more you earn.","More you work hard, the more you earn.","The harder you work more you earn."]'::jsonb, 'The harder you work, the more you earn.', 'the + 비교급, the + 비교급 구조를 따라야 합니다.'),
  ('english_grammar', 17, 'intermediate', '"It''s getting colder and colder."가 나타내는 의미는?', 'multiple_choice', '["점점 더 추워지고 있다","매우 춥다","이전보다 덜 춥다","춥지 않다"]'::jsonb, '점점 더 추워지고 있다', '비교급 + and + 비교급은 ''점점 더 ~해지다''라는 뜻입니다.'),
  ('english_grammar', 17, 'intermediate', 'far의 비교급으로 옳지 않은 것은?', 'multiple_choice', '["farer","farther","further","far의 비교급은 두 가지가 있음"]'::jsonb, 'farer', 'far의 비교급은 farther 또는 further이며 farer는 옳지 않습니다.'),
  ('english_grammar', 17, 'intermediate', '최상급을 강조하는 표현으로 옳은 것은?', 'multiple_choice', '["by far the most","much the most","even the most","still the most"]'::jsonb, 'by far the most', 'by far는 최상급을 강조하는 표현입니다.'),
  ('english_grammar', 17, 'intermediate', 'little의 비교급을 쓰시오.', 'short_answer', null, 'less', 'little의 비교급은 less입니다.'),
  ('english_grammar', 17, 'intermediate', '''점점 더 ~한''을 나타내는 구조를 쓰시오 (비교급 + ___ + 비교급).', 'short_answer', null, 'and', '비교급 + and + 비교급은 ''점점 더 ~한''이라는 뜻입니다.'),
  ('english_grammar', 17, 'advanced', '다음 중 어법상 옳은 것은?', 'multiple_choice', '["This is the more interesting of the two books.","This is the most interesting of the two books.","This is more interesting of the two books.","This is the interestingest of the two books."]'::jsonb, 'This is the more interesting of the two books.', '둘을 비교할 때는 최상급 대신 the + 비교급을 씁니다.'),
  ('english_grammar', 17, 'advanced', '"The sooner you start, the better."에서 생략된 것은?', 'multiple_choice', '["it will be (결과절 주어+동사)","you start","the sooner","아무것도 생략되지 않음"]'::jsonb, 'it will be (결과절 주어+동사)', 'the + 비교급 구문에서는 뒤의 주어+동사가 흔히 생략됩니다.'),
  ('english_grammar', 17, 'advanced', '다음 중 최상급의 의미를 원급으로 바꾼 것으로 옳은 것은? "He is the tallest boy in the class."', 'multiple_choice', '["No other boy in the class is as tall as him.","Every boy in the class is as tall as him.","He is not as tall as any boy in the class.","No boy in the class is taller than every boy."]'::jsonb, 'No other boy in the class is as tall as him.', '최상급은 ''다른 어떤 것도 ~만큼 ~하지 않다''는 원급 부정문으로 바꿀 수 있습니다.'),
  ('english_grammar', 17, 'advanced', '다음 중 어법상 틀린 것은?', 'multiple_choice', '["She is the most smartest student.","She is the smartest student.","She is smarter than anyone else.","No one is smarter than her."]'::jsonb, 'She is the most smartest student.', '최상급 -est와 most를 함께 쓰는 것은 이중 최상급 오류입니다.'),
  ('english_grammar', 17, 'advanced', '"This is by far the best solution."에서 by far의 역할은?', 'multiple_choice', '["최상급 강조","비교급 강조","동등 비교","부정"]'::jsonb, '최상급 강조', 'by far는 최상급을 강조하는 표현입니다.'),
  ('english_grammar', 17, 'advanced', '"The economy is growing faster than expected."에서 than 뒤에 생략된 것은?', 'multiple_choice', '["it was expected to grow","the economy expected","faster","growing"]'::jsonb, 'it was expected to grow', '비교 대상이 명확할 때는 반복되는 부분이 생략됩니다.'),
  ('english_grammar', 17, 'advanced', '둘을 비교할 때 최상급 대신 쓰는 표현을 쓰시오 (the + ___).', 'short_answer', null, '비교급', '둘을 비교할 때는 the + 비교급을 씁니다.'),
  ('english_grammar', 17, 'advanced', '''단연코''라는 뜻으로 최상급을 강조하는 표현을 쓰시오 (by ___).', 'short_answer', null, 'far', 'by far는 ''단연코''라는 뜻으로 최상급을 강조합니다.'),
  ('english_grammar', 18, 'beginner', '''quickly''는 어떤 종류의 부사인가?', 'multiple_choice', '["방법","장소","시간","빈도"]'::jsonb, '방법', 'quickly는 동작의 방법을 나타내는 부사입니다.'),
  ('english_grammar', 18, 'beginner', '''always''는 어떤 종류의 부사인가?', 'multiple_choice', '["빈도","방법","장소","정도"]'::jsonb, '빈도', 'always는 빈도를 나타내는 부사입니다.'),
  ('english_grammar', 18, 'beginner', '''yesterday''는 어떤 종류의 부사인가?', 'multiple_choice', '["시간","장소","빈도","정도"]'::jsonb, '시간', 'yesterday는 시간을 나타내는 부사입니다.'),
  ('english_grammar', 18, 'beginner', '"She always arrives early."에서 always의 위치 규칙은?', 'multiple_choice', '["일반동사 앞","일반동사 뒤","문장 끝","문장 맨 앞"]'::jsonb, '일반동사 앞', '빈도부사는 일반동사 앞에 위치합니다.'),
